    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">7<sup>63</sup> = 7<sup>62</sup> × 7</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">7<sup>63</sup> - 7<sup>62</sup> = 7<sup>62</sup>(7 - 1)</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">7 - 1 = 6</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">7<sup>63</sup> - 7<sup>62</sup> = 6 × 7<sup>62</sup></span>"},{"quoi":"نُظهر القاسم 21","math":"<span dir=\"ltr\" class=\"expr\">6 × 7<sup>62</sup> = 21 × (2 × 7<sup>61</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">21 × 2 × 7<sup>61</sup></span> و منه يقبل القسمة على 21"}],
