    correction: [{"quoi":"شرط القسمة على 5","math":"العدد يقبل القسمة على 5 إذا كان رقم آحاده 0 أو 5"},{"quoi":"رقم الآحاد معلوم","math":"رقم آحاد العدد 864a0 هو 0"},{"quoi":"الشرط لا يتعلّق بـ a","math":"الشرط يتعلّق برقم الآحاد وحده، و هو 0 مهما يكن a"},{"quoi":"نستنتج","math":"العدد يقبل القسمة على 5 مهما يكن a"},{"quoi":"الجواب","math":"صواب"}],
