    correction: [{"quoi":"نبحث عن الخارج","math":"أكبر مضاعف لـ 12 لا يفوق 5142 هو <span dir=\"ltr\" class=\"expr\">12 × 428</span>"},{"quoi":"نحسب هذا المضاعف","math":"<span dir=\"ltr\" class=\"expr\">12 × 428 = 5136</span>"},{"quoi":"نحسب الباقي","math":"<span dir=\"ltr\" class=\"expr\">5142 - 5136 = 6</span>"},{"quoi":"نتحقّق من الشرط","math":"<span dir=\"ltr\" class=\"expr\">6 &lt; 12</span>"},{"quoi":"نكتب القسمة الإقليدية","math":"<span dir=\"ltr\" class=\"expr\">5142 = 12 × 428 + 6</span>"},{"quoi":"الجواب","math":"خطأ"}],
