    correction: [{"quoi":"القاعدة","math":"لا يمكن جمع قوّتين إلاّ إذا كان لهما نفس الأساس"},{"quoi":"نوحّد الأساس في الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">9<sup>83</sup> = 3<sup>166</sup></span>"},{"quoi":"نعيد كتابة العدد","math":"<span dir=\"ltr\" class=\"expr\">3<sup>163</sup> - 9<sup>83</sup> = 3<sup>163</sup> - 3<sup>166</sup></span>"},{"quoi":"نُخرج أصغر قوّة","math":"<span dir=\"ltr\" class=\"expr\">3<sup>163</sup> - 3<sup>166</sup> = 3<sup>163</sup>(1 - 3<sup>3</sup></span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 - 3<sup>3</sup> = -26</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">3<sup>163</sup> - 9<sup>83</sup> = -26 × 3<sup>163</sup></span>"},{"quoi":"نُظهر القاسم 39","math":"<span dir=\"ltr\" class=\"expr\">-26 × 3<sup>163</sup> = 39 × ((-2) × 3<sup>162</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">39 × (-2) × 3<sup>162</sup></span> و منه يقبل القسمة على 39"}],
