    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">125<sup>237</sup> = 5<sup>711</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>711</sup> + n × 5<sup>710</sup> = 5<sup>710</sup>(5 + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">20 = 5 × 4</span>"},{"quoi":"العامل 5 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">5<sup>710</sup> = 5 × 5<sup>709</sup></span>"},{"quoi":"يبقى الشرط على 4","math":"بما أنّ 4 و 5 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">5 + n</span> القسمة على 4"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">5 = 5</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 50 بحيث يقبل <span dir=\"ltr\" class=\"expr\">5 + n</span> القسمة على 4"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 3 ؛ 7 ؛ 11 ؛ 15 ؛ 19 ؛ 23 ؛ 27 ؛ 31 ؛ 35 ؛ 39 ؛ 43 ؛ 47</span>"}],
